contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }
    function testFuzz_property(address newOwner) public {
        vm.prank(c.owner());
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        if (newOwner == address(0)) {
            assertFalse(ok);
        } else {
            assertTrue(ok && c.owner() == newOwner);
        }
    }
}
